# Z2409 / FRONTIER §7.3 diagnostic: classify failing (★) levels t = 4C (N = tp+1 has no divisor ≡ −1 mod t) by WHICH
# character structure explains the failure:
#  A = BM: every prime factor q of N has χ_{−t}(q) = +1 (kernel of the BM Kronecker character)
#  B = other odd REAL (genus) character: −1 ∉ <H, G²>, not A
#  C = higher-order odd character: −1 ∉ H but −1 ∈ <H, G²>
#  D = no character: −1 ∈ H = <prime classes>, yet no divisor (subset product with exponents ≤ v_q) is ≡ −1
# H = subgroup of G = (Z/t)^× generated by prime factors of N. Zeros of (★) (all levels fail) vs controls.
import random, math
from math import gcd
Z=[409,577,5569,9601,23929,83449,102001,329617,712321,1134241,1724209,1726201,5212561,8813281]
def factor(n):
    f={};d=2
    while d*d<=n:
        while n%d==0: f[d]=f.get(d,0)+1; n//=d
        d+=1 if d==2 else 2
    if n>1: f[n]=f.get(n,0)+1
    return f
def isprime(n): return n>1 and factor(n)=={n:1}
def jac(a,n):
    a%=n; r=1
    while a:
        while a%2==0:
            a//=2
            if n%8 in (3,5): r=-r
        a,n=n,a
        if a%4==3 and n%4==3: r=-r
        a%=n
    return r if n==1 else 0
def kron_mt(t,q): # (−t / q) for odd prime q ∤ t
    return jac(-t % q, q)
def closure(gens,t):
    S={1};fr=[1]
    while fr:
        x=fr.pop();
        for g in gens:
            y=x*g%t
            if y not in S: S.add(y); fr.append(y)
    return S
def classify(p,C):
    t=4*C; N=t*p+1; f=factor(N)
    divs=[1]
    for q,e in f.items(): divs=[d*q**k for d in divs for k in range(e+1)]
    if any(d%t==t-1 for d in divs): return None  # level succeeds
    if all(kron_mt(t,q)==1 for q in f): return 'A'
    G=[a for a in range(1,t) if gcd(a,t)==1]
    H=closure([q%t for q in f],t)
    if t-1 not in H:
        H2=closure([q%t for q in f]+[a*a%t for a in G],t)
        return 'B' if t-1 not in H2 else 'C'
    return 'D'
def run(ps,Cmax):
    cnt={'A':0,'B':0,'C':0,'D':0}
    for p in ps:
        for C in range(1,Cmax+1):
            r=classify(p,C)
            if r: cnt[r]+=1
    tot=sum(cnt.values()); return cnt, {k:round(v/tot,3) for k,v in cnt.items()}
random.seed(1)
ctrl=[]
while len(ctrl)<14:
    p=random.randrange(10**5,9*10**6)
    if p%24==1 and isprime(p): ctrl.append(p)
print('zeros   ',run(Z,40))
print('controls',run(ctrl,40))
